"""Build the revised IEEE-style submission documents from code-aligned structured sources.

Run with python-docx installed, then convert the three DOCX files to PDF with
LibreOffice using an isolated profile. Figures are regenerated by build_diagrams.py.
"""
from pathlib import Path
import json
from datetime import datetime, timezone
from docx import Document
from docx.shared import Inches,Pt,RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
ROOT=Path(__file__).resolve().parents[2];DOCS=ROOT/'docs'
REQ=json.loads((DOCS/'source/requirements.json').read_text());CASES=json.loads((DOCS/'source/test_cases.json').read_text())
DATE='12 November 2026'; BASE='6b5464298c949806ebba0b7bd1d903c962b5255d'
TEAM=[['Deeptanshu Kumar','PES1UG24AM357','Developer'],['Amar','PES1UG24AM340','Tester'],['Aaryaprasad','PES1UG24AM331','Product Owner']]
def para(d,text,style=None):return d.add_paragraph(text,style)
def heading(d,text,level=1):d.add_heading(text,level)
def table(d,headers,rows,widths=None):
 t=d.add_table(rows=1,cols=len(headers));t.style='Light Shading Accent 1'
 for c,s in zip(t.rows[0].cells,headers):c.text=str(s)
 for row in rows:
  cells=t.add_row().cells
  for c,s in zip(cells,row):c.text=str(s)
 for row in t.rows:
  for idx,c in enumerate(row.cells):
   if widths:c.width=Inches(widths[idx])
   for p in c.paragraphs:
    p.paragraph_format.space_after=Pt(2)
    for r in p.runs:r.font.size=Pt(9)
  if headers[0]=='Reviewer' and row is not t.rows[-1]:
   for cell in row.cells:
    for pp in cell.paragraphs:pp.paragraph_format.keep_with_next=True
  pr=row._tr.get_or_add_trPr();keep=OxmlElement('w:cantSplit');pr.append(keep)
 if headers[0]=='Reviewer':
  for cell in t.rows[-1].cells:
   for pp in cell.paragraphs:pp.paragraph_format.keep_with_next=False
 pr=t.rows[0]._tr.get_or_add_trPr();rep=OxmlElement('w:tblHeader');pr.append(rep)
 return t

def new(title,baseline):
 d=Document();sec=d.sections[0];sec.page_width=Inches(8.27);sec.page_height=Inches(11.69)
 sec.top_margin=sec.bottom_margin=Inches(.7);sec.left_margin=sec.right_margin=Inches(.75)
 for name in ['Normal','Body Text','List Bullet','List Number']:
  s=d.styles[name];s.font.name='Times New Roman';s.font.size=Pt(11);s.paragraph_format.space_after=Pt(6);s.paragraph_format.line_spacing=1.08
 for name,size in [('Title',23),('Heading 1',15),('Heading 2',12),('Heading 3',11)]:
  s=d.styles[name];s.font.name='Calibri';s.font.size=Pt(size);s.font.color.rgb=RGBColor.from_string('000000')
 for border in list(d.styles['Title'].element.xpath('.//w:pBdr')):border.getparent().remove(border)
 d.core_properties.created=datetime.now(timezone.utc);d.core_properties.modified=datetime.now(timezone.utc)
 d.core_properties.author='Deeptanshu Kumar';d.core_properties.title=title;d.core_properties.subject='Railway Ticket Reservation System final submission'
 d.add_paragraph(title,'Title');para(d,'Railway Ticket Reservation System');para(d,f'Version 2.0 | Revised {DATE} | Team 15 | UE24CS341A')
 para(d,'This revision specifies the delivered C++ application and its verification evidence. It aligns the submission documents with the implementation and identifies the remaining team acceptance actions. It is prepared for review; signatures and acceptance are not implied.')
 table(d,['Team member','USN','Role'],TEAM)
 heading(d,'Revision history',2);table(d,['Version','Date','Change'],[['1.0',baseline,'Original submitted baseline; retained in repository history'],['2.0',DATE,'Reconcile actual stack, interfaces, policies, traceability and current verification evidence']])
 para(d,f'Application baseline: {BASE}. The final feature integration is main commit fb1b4d55957ab8022e136396d656bec870c08375, merged by Amar in PR 12 on 3 November 2026. Current evidence was generated on 12 November 2026.')
 foot=sec.footer.paragraphs[0];foot.alignment=2;r=foot.add_run('Railway Ticket Reservation System | ');r.font.size=Pt(8);f=OxmlElement('w:fldSimple');f.set(qn('w:instr'),'PAGE');foot._p.append(f)
 return d

def image(d,name,caption):
 d.add_picture(str(DOCS/'diagrams'/name),width=Inches(6.65));p=d.add_paragraph(caption);p.style='Caption'

def bullets(d,items):
 for x in items:para(d,x,'List Bullet')

def rtm(d):
 table(d,['Requirement','Module','Test case references'],[[r['id'],r['module'],', '.join(r['cases'])]for r in REQ],[1,1.8,3.9])
 para(d,'Named automated tests are listed in the Test Plan and source/test_cases.json. Passing unit/API checks, system assertions and selected browser observations are distinct evidence types. Human UAT and PO/mentor acceptance remain pending; the matrix is not a fabricated sign-off.')

def references(d):
 bullets(d,['Course Mini Project Deliverables Parts 1, 2 and 3; evaluation checklist; final demo and viva FAQs.','Repository README, CMakeLists.txt, src/api, src/services, src/db and tests at the application baseline above.','IEEE 830 style requirements structure; IEEE 1016 style software design description; IEEE 829 style test planning structure, adapted to the supplied course templates.','docs/SUBMISSION_INDEX.md for the deliverable inventory; docs/DEVIATIONS.md for baseline differences; docs/reports for actual results.'])

def approvals(d):
 table(d,['Reviewer','Review responsibility','Signature and actual date'],[['Amar','Test Plan and verification review','Pending'],['Aaryaprasad','Requirements and policy acceptance','Pending'],['Rajeshwari Adarakatti','Mentor evaluation','Pending']])

def requirements(d,prefix):
 for idx,r in enumerate([r for r in REQ if r['id'].startswith(prefix)],1):
  heading(d,r['id']+' '+r['title'],2);para(d,r['text']);para(d,'Acceptance: '+r['acceptance']);para(d,'Priority: '+r['priority']+'. Traceability: '+', '.join(r['cases'])+'. Module: '+r['module']+'.')

def make_srs():
 d=new('Software Requirements Specification','6 September 2026')
 heading(d,'1 Introduction');heading(d,'1.1 Purpose and audience',2);para(d,'The system lets passengers search demonstration train records, inspect fares and inventory, book tickets, view history and cancel eligible reservations. This specification is the requirements baseline for developers, tester, product owner, mentor and evaluator. Each requirement has an identifier, measurable acceptance condition and test reference.')
 heading(d,'1.2 Scope',2);para(d,'The academic web application covers passenger accounts, search, train schedules, availability, passenger entry, confirmation, unique PNR, ticket/history, cancellation/refund recording, administrator train maintenance and booking/cancellation audit events. Real railway operations, live timetable integration and payment settlement are excluded.')
 heading(d,'1.3 Definitions and references',2);table(d,['Term','Meaning'],[['FR / NFR','Functional / Non-Functional Requirement'],['PNR','Random ten-digit booking reference'],['RTM','Requirements Traceability Matrix'],['RBAC','Role-based access control'],['Opaque session','Random bearer token resolved through server-side storage'],['UTC','Time basis used by schedule/cancellation calculations']]);references(d)
 heading(d,'2 Overall description');heading(d,'2.1 Product perspective',2);para(d,'A browser client built with HTML, CSS and JavaScript calls a C++17 JSON REST server. Business services persist data through prepared SQLite statements and transactions. The server serves static assets and can terminate TLS directly. This replaces the original SAD React/Node/Express/MySQL/JWT examples without changing the central reservation use cases.')
 heading(d,'2.2 Roles and functions',2);table(d,['Role','Capabilities'],[['Passenger','Register/login/logout; profile; search/schedule/fare/availability; own booking/ticket/history/cancellation'],['Administrator','Passenger capabilities plus add/update/deactivate trains and read booking audit records'],['Tester and Product Owner','Verify acceptance, track defects and approve documented policy/design changes']])
 heading(d,'2.3 Environment and constraints',2);bullets(d,['Server: C++17 compiler, CMake 3.20 or newer, OpenSSL and SQLite amalgamation; Linux build and Docker packaging provided. Client: a modern JavaScript-enabled browser.','Inventory and fares are whole train/date/class values. There is no segment-level seat reuse or distance pricing; booking does not store boarding/destination stations.','Dates must be real YYYY-MM-DD values. There is no operating-day calendar, and the backend currently permits past dates; the demonstration uses future dates.','Default policy is 24 hours before the current origin departure and 90 percent of stored fare, rounded down to whole rupees. Departure/day offsets are interpreted as UTC. These project defaults require genuine policy acceptance.','Preview does not hold seats. Confirmation rechecks current inventory and fare transactionally. Client retries have no idempotency key and may create another booking if capacity remains.','Refund amounts are recorded, not transferred. No payment state machine or production railway integration is delivered.'])
 heading(d,'3 External interface requirements');heading(d,'3.1 User interface',2);para(d,'Provide labelled registration/login/profile forms; search criteria and filters; results with train number/name, departure/arrival, duration and starting fare; details with schedule and class availability; passenger form, preview, ticket, history and cancellation confirmation. Admin screens maintain trains. Validation messages identify fields and navigation remains usable at desktop and mobile sizes. Availability is shown in train details rather than directly on every search card, a documented baseline difference.')
 heading(d,'3.2 Hardware and software interfaces',2);para(d,'No dedicated railway hardware is required. The browser uses JSON over HTTP/HTTPS. The C++ process accesses one local SQLite database file. OpenSSL supplies password hashing, secure randomness and optional TLS. Environment variables select database, port, web directory, policy and TLS files. Administrator promotion is a local CLI operation, not public registration.')
 heading(d,'3.3 Communication',2);para(d,'Credentials are submitted in JSON bodies and bearer tokens in Authorization headers. Protected requests resolve identity from the session, never a user ID supplied by the client. Deployed transport must use configured TLS or a controlled TLS-terminating proxy. Secrets are excluded from URLs, logs and error messages.')
 heading(d,'4 Functional requirements');requirements(d,'RTS-F-')
 heading(d,'5 Non Functional Requirements');requirements(d,'RTS-NF-')
 heading(d,'5.1 Security objectives',2);bullets(d,['SO-1 Protect passenger accounts and reservation information against unauthorized disclosure and modification.','SO-2 Preserve the integrity of reservation, cancellation and inventory state under invalid and concurrent requests.'])
 heading(d,'5.2 Security requirements',2);requirements(d,'RTS-SR-')
 heading(d,'6 Quality attributes and acceptance');para(d,'Correctness is evaluated through inventory/PNR/refund invariants; reliability through rollback and restart scenarios; security through credential, role, owner, TLS and input checks; usability through selected browser viewports. All high-priority requirements need passing evidence or an explicit accepted disposition. No critical unresolved defect should block acceptance. The current automated reports do not substitute for team UAT or signatures.')
 table(d,['Evidence','Current result and limit'],[['Unit and API suite','201 tests across 49 suites pass; not 201 distinct STP cases'],['System validation','122 assertions pass; small local dataset, real subprocess HTTP/TLS and restart checks'],['Coverage','94.7% lines and 46.7% branches in C++ src excluding main.cpp; not browser/deployment coverage'],['Responsive UI','Selected 1366×900 desktop and 390×844 mobile observations; physical-device/cross-browser acceptance not established']])
 heading(d,'7 System models');image(d,'use_cases.png','Figure 1 Passenger and administrator use cases');para(d,'Passenger operations require authentication where they access private records. Administrator operations add a current database role check. Booking/cancellation service rules enforce inventory consistency and ownership independently of UI controls.')
 heading(d,'8 Requirements traceability');rtm(d)
 heading(d,'9 Open acceptance actions');bullets(d,['Tester reviews reports, runs final human acceptance and uploads the two sprint videos through the designated friend.','Product Owner reviews policy defaults, scope limitations and stack/interface deviations.','Connect current Jira to reconcile the dated 13 October snapshot with later dates/statuses; GitHub course milestones remain separate from original Jira sprints.']);approvals(d)
 d.save(DOCS/'Railway_Ticket_Reservation_System_SRS.docx')

API=[['POST /api/auth/register','name,email,phone,password','201 user; 400 fields; 409 duplicate','Public'],['POST /api/auth/login','email,password','200 token, expiry, user; 401/429','Public'],['POST /api/auth/logout','Bearer header','200 ended session;401','Session'],['GET /api/users/me','Bearer header','200 own user','Session'],['PUT /api/users/me','name,phone','200 own profile; 400 fields','Session'],['PUT /api/users/me/password','currentPassword, newPassword','200;revoke other sessions','Session'],['GET /api/trains/search','source, destination, date; optional class, maxFare, departureFrom/To, sort, order','200 trains/date; 400 fields','Public'],['GET /api/trains/{id}/schedule','Numeric train ID','200 ordered stops;404','Public active train'],['GET /api/trains/{id}/availability','date query','200 classes with counts; 400/404','Public active train'],['GET /api/trains/{id}/fares','Numeric train ID','200 class fares;404','Public active train'],['POST /api/bookings/preview','trainId, date, class, passengers','200 preview;400/409','Session'],['POST /api/bookings','Same booking fields','201 booking and PNR; 400/409','Session'],['GET /api/bookings','Bearer header','200 own bookings','Session'],['GET /api/bookings/{pnr}','Numeric PNR, not internal ID','200 ticket; 404 other owner/unknown','Owner'],['GET /api/bookings/{id}/cancellation','Internal booking ID','200 eligibility/refund quote; 404','Owner'],['PUT or POST /api/bookings/{id}/cancel','Internal booking ID','200 cancelled ticket; 409 ineligible','Owner'],['GET /api/admin/me','Bearer header','200 admin;401/403','Admin'],['GET /api/admin/trains','Bearer header','200 full train records','Admin'],['GET /api/admin/trains/{id}','Numeric train ID','200 full record;404','Admin'],['POST /api/admin/trains','number,name,stops,classes','201; 400 invalid; 409 duplicate','Admin'],['PUT /api/admin/trains/{id}','Replacement record','200; 409 capacity/class conflict','Admin'],['PUT /api/admin/trains/{id}/deactivate','Numeric train ID','200 inactive service','Admin'],['GET /api/admin/audit','limit 1–500, default 100','200 newest events first','Admin'],['GET /api/health','None','200 status ok','Public']]

def make_sad():
 d=new('Software Architecture and Design Specification','30 September 2026')
 heading(d,'1 Introduction');para(d,'This design translates the identified requirements into the delivered C++ components, interfaces, database and transaction behavior. It supports maintainability, testability and explanation during the final demo. The original version described React/Express and a generic SQL database; this revision documents the actual implementation and records deviations without inventing approval.')
 references(d)
 heading(d,'2 Design context and decisions');table(d,['Concern','Decision and rationale'],[['Academic C/C++ requirement','Implement all reservation business services and HTTP backend in C++17'],['Simple browser delivery','Serve static HTML/CSS/JavaScript from the same server; no Node/React runtime needed'],['Persistent consistent records','Embedded SQLite with foreign keys, prepared statements, transaction mutex, busy timeout and immediate transactions'],['Testability','Keep routes separate from main; services accept database and test configuration; GoogleTest uses isolated fixtures'],['Deployment simplicity','Single executable with web assets; Docker image publication through GitHub Actions; hosted service deployment not claimed']])
 heading(d,'3 Architecture');heading(d,'3.1 Pattern and boundaries',2);para(d,'Use a layered architecture: presentation, HTTP/API coordination, application services, and persistence. Cross-cutting validation, hashing, authorization, TLS and logging support the services. One server process shares a serialized Database wrapper; tests do not establish independent multi-process scalability.')
 image(d,'components.png','Figure 1 C++ layered component architecture')
 heading(d,'3.2 Component responsibilities',2);table(d,['Component','Responsibility','Requirements'],[['web/','Forms, search/results, train details, preview, ticket/history/cancellation, admin editor','FR001–017;NF007'],['Routes and AdminRoutes','HTTP/JSON parsing, status codes, authenticated owner/admin gates','All API requirements'],['UserService and AuthService','Profiles, passwords, opaque sessions, expiry, lockout and revocation','FR001/002; NF005/006; SR001/002'],['TrainService','Search filters, ordered stops, fares and train/date/class availability','FR003–005'],['BookingService','Validation, preview, atomic confirmation/PNR/seats, owned cancellation/refund','FR006–016;NF002'],['AdminTrainService','Transactional add/update/deactivate with reservation safeguards','FR017'],['AuditService and Log','Booking/cancellation audit and redacted access logging','FR018;NF008;SR005'],['Database and Schema','RAII connection/statements, mutex, prepared binding and schema constraints','Persistence and consistency'],['Validation and TlsConfig','Type/length/enum/date checking; certificate/key configuration','NF003;SR003/004']])
 heading(d,'3.3 Technology and data stores',2);para(d,'C++17, CMake, cpp-httplib 0.18.3, nlohmann/json 3.11.3, SQLite 3.46.1 amalgamation, OpenSSL and GoogleTest 1.15.2. GCC/gcov and gcovr supply coverage; cppcheck and CodeQL provide static checks. No JWT parser, React build, Express server or MySQL server is needed.')
 heading(d,'3.4 Security architecture',2);bullets(d,['PBKDF2-HMAC-SHA256 with random 16-byte salts and default 600000 iterations; configured production minimum 100000. Constant-time comparison and upgrade of older hashes on successful login.','Random 256-bit opaque bearer token returned once; only SHA-256 token hash stored with 24-hour expiry. Logout deletes session. Password change revokes other sessions. Browser stores token in sessionStorage; no HttpOnly-cookie design is claimed.','Authorization always derives user from current session. Admin endpoints reread the current database role. Other-owner booking requests return 404 to avoid disclosing existence; passenger admin attempts return 403.','Bound SQL values and explicit field validation; 64 KB request limit; output escaping in browser code. Server failures return generic JSON, never SQL/stack/credential details.','TLS certificate/key variables enable an SSLServer. HTTP default is development-only or behind a configured TLS proxy. HSTS depends on HTTPS indication; forwarded headers require a trusted deployment boundary.','Audit events share booking/cancellation transactions. Application behavior is append-only, not tamper-proof against direct database administrators. Access logs omit query values, bodies, headers and redact sensitive text.'])
 heading(d,'3.5 Data model',2);table(d,['Table','Key relationships and stored data'],[['users','id PK; unique email; name, phone, password_hash, role, created_at'],['sessions','token_hash PK; user_id FK; expires_at'],['trains','id PK; unique number; name, active flag'],['train_stops','train_id FK; station, arrival/departure, day_offset, ordered sequence'],['train_classes','train_id FK; class code/name, fare, total_seats'],['bookings','id PK; unique PNR; user/train/class/date; status, stored fare, quantity, cancel/refund fields'],['passengers','booking_id FK; name, age, gender, assigned seat'],['seat_reservations','booking/train/date/class; reserved quantity used by availability'],['audit_events','event type, time, actor, booking, train, PNR and refund identifiers']])
 para(d,'There is no separate payment or cancellation table. Fare is snapshotted in bookings; current train/class labels are loaded when displaying details. A duplicate-seat trigger rejects conflicting confirmed seat allocations. Cancellation removes inventory reservations while preserving ticket/passenger history. Admin updates cannot remove referenced classes or reduce capacity below existing reservations/assigned seat numbers.')
 heading(d,'4 Detailed design');heading(d,'4.1 Booking algorithm',2);para(d,'Validate the authenticated user, train/date/class and one to six passengers (name, age 1–120, gender M/F/O). Preview calculates current fare/quantity and holds no inventory. Confirmation enters BEGIN IMMEDIATE, rechecks active train/class/availability, chooses free seat numbers, generates a random ten-digit unique PNR, inserts booking/passengers/reservation and audit, then commits. Exceptions roll back all writes. Displayed availability is provisional; no idempotency protection is provided for successful client retries.')
 d.add_page_break();heading(d,'4.2 Booking sequence',2);image(d,'booking_sequence.png','Figure 2 Successful booking sequence');para(d,'Seat and audit changes occur in one transaction. Validation, authorization and conflict alternatives return before a successful confirmation; rollback removes partial writes.')
 d.add_page_break();heading(d,'4.3 Cancellation sequence',2);image(d,'cancellation_sequence.png','Figure 3 Owner cancellation with refund recording');para(d,'Quote and confirmation both enforce ownership. Confirmation rechecks eligibility using the current first-stop departure in UTC, marks the whole booking CANCELLED, records timestamp and floor(totalFare × percent / 100), removes reservation rows and records audit atomically. Repeated cancellation returns conflict without another refund/restoration.')
 heading(d,'4.4 API specification',2);table(d,['Method and endpoint','Inputs','Result','Access'],API)
 heading(d,'4.5 Payload contracts',2);para(d,'Booking example: {"trainId":2, "date":"YYYY-MM-DD", "class":"SL", "passengers":[{"name":"Demo Passenger", "age":"22", "gender":"M"}]}. The authenticated user ID is never accepted from the body. Registration requires phone as well as name, email, password. Dates use the key date, not the original SAD placeholder journeyDate. Ticket retrieval uses PNR; cancellation uses internal numeric booking ID.')
 para(d,'Train payloads contain five-digit number, name, ordered stops and classes. Stops have station, arrival, departure and integer dayOffset 0–30; origin arrival and terminal departure are blank. Classes have code SL/3A/2A/1A/CC/EC, name, integer fare 1–1000000 and totalSeats 1–10000. Updates replace the submitted record atomically, subject to booking safeguards.')
 heading(d,'4.6 Error handling and observability',2);table(d,['Status','Meaning','State invariant'],[['400','Malformed JSON, wrong types, invalid fields/date','No booking/admin mutation on validation failure'],['401','Absent, expired, revoked or invalid session','Protected resources unavailable'],['403','Authenticated passenger accessing admin operation','No admin write'],['404','Unknown or other-owner booking; inactive public train','No resource-existence disclosure for private booking'],['409','Sold out, duplicate email/train, ineligible cancel, capacity conflict','No partial write or duplicate restoration'],['413 /405','Oversized payload/unsupported method','Generic JSON failure'],['429','Login attempt lockout','No successful session issued while locked'],['500','Unexpected internal failure','Generic response; transaction rollback']])
 heading(d,'5 Deployment and operations');para(d,'Build with cmake -S . -B build and cmake --build build -j. Run rtrs_server with RTRS_DB pointing to a writable SQLite file and RTRS_WEB_DIR to web assets. RTRS_PORT defaults to 8080. Set both RTRS_TLS_CERT and RTRS_TLS_KEY for direct HTTPS. The local --promote-admin EMAIL command grants a registered account the role and revokes its existing sessions. There are no default admin credentials.')
 para(d,'CI builds/tests, stores raw XML/coverage, runs actual executable validation, cppcheck, CodeQL and a Docker smoke test. Main-branch CD publishes an image to GHCR; it does not deploy a hosted service. Backup/restore must account for SQLite WAL, and a clean same-database restart preserves committed records. Current system evidence covers selected restart/forced-stop scenarios, not all storage failures.')
 heading(d,'6 Traceability and validation');rtm(d);para(d,'Refer to the four reports and browser observations in docs/reports. Local results are 201 passing tests, 122 passing system assertions, 94.7% line coverage and 46.7% branch coverage in the stated scope. A trusted temporary test certificate established a real TLS 1.3 handshake. Human review and policy acceptance remain pending.')
 d.add_page_break();heading(d,'7 Limitations and future work');bullets(d,['Add operating-day/future-date rules, segment inventory/pricing and richer journey snapshots if future requirements demand them.','Introduce request idempotency before treating network retries as exactly-once reservations.','Evaluate multiple independent SQLite connections/processes and larger realistic load before scale claims.','Review policy defaults, current-schedule cancellation effects, browser token storage and production proxy trust.','No real payment settlement, external railway integration or tamper-proof audit store is claimed.']);approvals(d)
 d.save(DOCS/'Railway_Ticket_Reservation_System_SAD_Final.docx')

def make_stp():
 d=new('Software Test Plan','2 October 2026')
 heading(d,'1 Introduction');para(d,'This plan defines verification of the Railway Ticket Reservation System against its FR, NFR and security requirements. It covers scope, strategy, environment, roles, schedule, test cases, traceability and reporting. Version 2 reconciles actual C++ test tooling and new evidence; planned test steps are not represented as personal manual execution or signed acceptance.');references(d)
 heading(d,'2 Test items');bullets(d,['Passenger account/profile/session services; train search, schedule, fares and inventory.','Passenger validation, booking preview/confirmation, PNR, tickets and history.','Cancellation policy, refund recording, seat restoration and booking ownership.','Administrator train lifecycle, audit/access logging, validation, TLS, concurrency, recovery and responsive UI.'])
 heading(d,'3 Features to be tested');rtm(d)
 heading(d,'4 Features not tested');bullets(d,['Real railway operational control, live railway feeds and physical railway hardware.','Payment-provider settlement, bank refunds and external financial-system behavior.','Production-scale distributed load, power-loss durability, full penetration-test certification and every browser/device/accessibility combination. These exclusions do not remove the required local NFR/security checks.'])
 heading(d,'5 Test approach and strategy');heading(d,'5.1 Security validation',2);table(d,['Control','Procedure and evidence'],[['Password storage','Inspect DB salted PBKDF2 hashes; negative credentials; rehash; TC-SEC-01 and automated XML'],['Authorization','Missing/revoked tokens, ordinary-user admin requests, cross-owner booking access; TC-SEC-02/03'],['Transport','Verify TLS configuration/headers plus actual executable handshake with hostname verification and temporary trusted test certificate; TC-SEC-04'],['Input safety','Malformed JSON, wrong types, SQL/script-like values, boundaries and a 64 KB limit; TC-SEC-05'],['Sensitive logging','Inspect redaction, no auth body/header/query logging and safe errors; TC-SEC-06']])
 heading(d,'5.2 Levels and techniques',2);para(d,'GoogleTest exercises pure validators, hashing, service rules, database rollback and HTTP API integration. The stdlib Python runner launches the actual executable with fresh temporary SQLite files and ephemeral ports. Browser observations exercise actual DOM forms and rendering. Apply equivalence partitioning, boundary values, state transitions, negative authorization and concurrent inventory tests. Human UAT remains a separate tester/product-owner activity.')
 heading(d,'5.3 Entry criteria',2);bullets(d,['A buildable identified revision with initialized controlled data and reachable APIs.','Isolated synthetic passenger/admin credentials and no use of production reservation data.','Required compiler, CMake, OpenSSL, Python, GoogleTest and reporting tools available; planned scenarios not blocked by a known build failure.'])
 heading(d,'5.4 Exit criteria and acceptance',2);bullets(d,['Execute all planned cases or document unexecuted/blocked cases and obtain genuine disposition.','No open critical defect blocks core workflows; mandatory FR/NFR/security evidence is reviewed.','Store Unit, System Validation, Code Coverage and Branch Coverage reports under docs; keep actual run dates, revision and raw results.','Tester and PO complete human acceptance and reviewer approvals; automated checks alone do not satisfy signature or demo requirements.'])
 heading(d,'5.5 Data isolation and reset',2);para(d,'GoogleTest uses controlled in-memory fixtures with reduced PBKDF2 iterations where appropriate. The executable runner uses the default server security configuration, random temporary passwords, disposable file-backed SQLite and temporary TLS certificates. It removes its own temporary data and logs no secrets. Browser rehearsal uses a separate synthetic database. Restart and compare data before reset; never delete a user database as a shortcut.')
 heading(d,'6 Test environment');table(d,['Item','Executed configuration or procedure'],[['Application','C++17/cpp-httplib/SQLite; Debug build with RTRS_COVERAGE=ON'],['Compiler/platform','GCC 16.2.1 on Fedora Linux; exact platform in execution-metadata.json'],['Unit/tooling','GoogleTest/CTest, gcov/gcovr 8.8; src-only coverage excluding main.cpp'],['System runner','Python stdlib, localhost HTTP/HTTPS, openssl executable, temporary DB'],['Browser','Chrome isolated context; desktop 1366×900, mobile 390×844'],['Seed route','Pune Jn→Mumbai CSMT; Deccan Express 11007; SL fare 190, fresh capacity 300'],['Policy','Default 24-hour cutoff, 90 percent refund, whole-rupee rounding; UTC departure'],['Scope limit','Small local dataset; not production latency or physical-device certification']])
 heading(d,'7 Schedule and responsibilities');table(d,['Milestone','Course planned window','Actual evidence'],[['Requirements/design baseline','28 Sept 2026','Original SRS/SAD/STP revisions retained in Git'],['Backlog preparation','12 Oct 2026','Historical Jira snapshot 13 Oct; GitHub migration 12 Nov'],['Sprint 1','19–23 Oct 2026','Search/booking delivery 20 Oct; earlier auth foundation'],['Sprint 2','26–30 Oct 2026','Cancellation delivery 29 Oct'],['Optional Sprint 3 / testing','2–6 Nov 2026','Admin/security final feature delivery 3 Nov'],['Submission verification refresh',DATE,'Fresh 201-test, 122-check, coverage and browser reports']]);table(d,['Person','Responsibility'],[[n,f'{role}; USN {usn}']for n,usn,role in TEAM]);para(d,'Deeptanshu provides build, implementation and automated verification. Amar reviews the plan, executes human acceptance, tracks defects and reviews integration. Aaryaprasad confirms requirements/priorities/policy and acceptance. Actual individual repository evidence is separated in docs/demo/VIVA_PREP.md.')
 heading(d,'8 Test deliverables');bullets(d,['This Test Plan with detailed cases and RTM; source/test_cases.json and source/requirements.json.','reports/Unit_Test_Report.pdf and .md; unit-tests.xml; ctest-results.xml.','reports/System_Validation_Report.pdf and .md; system_validation.json.','reports/Code_Coverage_Report.pdf and .md; reports/Branch_Coverage_Report.pdf and .md; coverage JSON and HTML.','reports/Browser_Validation_Report.md and genuine UI screenshots.','Defect dispositions, actual human acceptance and videos remain team actions; blank approvals are not manufactured.'])
 heading(d,'9 Risks and mitigation');table(d,['Risk','Mitigation'],[['Dirty/stale data','Fresh fixtures; identified source/binary; per-run raw records'],['Double booking/partial write','Concurrent buyers, DB trigger and rollback failure scenarios'],['Stale availability','Preview versus confirmation conflict tests'],['Timing/cutoff flakiness','Future journey fixture and explicit UTC/default policy'],['Overstated coverage','Separate line/branch, exclude main/browser explicitly; retain raw counts'],['Historical misattribution','Preserve original Git/Jira capture times; label retrospective course planning']])
 heading(d,'10 Assumptions and dependencies');para(d,'Seed records are synthetic. APIs and routes reflect the actual revision. Policy defaults are used for reproducible tests but require product acceptance. A successful test does not establish an unexecuted browser scenario or a human reviewer identity. The original Jira snapshot is dated 13 October; later live updates need reconnection.')
 heading(d,'11 Suspension and resumption');para(d,'Suspend testing if the executable will not start, critical test data is unavailable, or a blocker prevents the core flow. Record the blocking check and do not report an incomplete runner as PASS. Resume after fixing the blocker, rebuilding and repeating affected checks. Preserve failed-run evidence and correct the RTM.')
 heading(d,'12 Requirement traceability and execution interpretation');rtm(d);para(d,'The 201 GoogleTests are not 201 detailed plan cases. The 46 cases below map to named tests and/or system/browser evidence. A passing automated check supports its asserted behavior; it does not claim every written manual step was personally replayed. System JSON contains 122 actual assertions. TC-REC-01 and TC-UX-01 use their specific reports. TC-PERF-01 combines local search/booking measurements with the stated limits.')
 heading(d,'13 Defect and change management');para(d,'Record an actual failed scenario with revision, inputs, expected and actual results, severity, owner and evidence. Retest after a fix and link the commit/PR. No synthetic defect closure list or invented review is supplied. Changes to requirements, architecture or policy update the SRS, SAD, Test Plan and affected cases together.')
 heading(d,'14 Detailed test cases');para(d,'Unless noted otherwise, use a fresh isolated database, synthetic users and a future date at least three days ahead. Apply authentication required by the case. Steps define reproducible tests; current outcomes are available in the linked reports rather than implied human signatures.')
 for c in CASES:
  heading(d,c['id']+' '+c['title'],2);para(d,'Requirements: '+', '.join(c['requirements'])+'. Method: '+c['kind']+'.');para(d,'Inputs and preconditions: '+c['inputs'])
  for i,step in enumerate(c['steps'],1):para(d,f'{i}. {step}')
  para(d,'Expected: '+c['expected']);para(d,'Automated evidence: '+('; '.join(c['tests']) if c['tests'] else 'See '+('System_Validation_Report and raw JSON' if c['id']=='TC-REC-01' else 'Browser_Validation_Report and screenshots'))+'.')
 heading(d,'15 Metrics and reporting');para(d,'Current local verification: 201 tests across 49 suites pass; 122 system assertions pass; line coverage is 1476/1558 (94.7%); branch coverage is 3162/6778 (46.7%); function coverage is 167/167 (100%) in the measured scope. Search p90 is 0.002256 seconds and booking p90 is 0.006130 seconds, each with 20 requests and four clients. The course testing window is historical; these fresh runs are dated 12 November 2026.')
 para(d,'Review planned case execution, pass/fail/blocked counts, requirement coverage, defect severity/retest state, latency method and coverage counts separately. No minimum coverage percentage was given in the five handouts. An absence of failed automated checks does not prove zero defects or completed human acceptance.')
 heading(d,'16 Review and approvals');approvals(d)
